CREATE COLUMN TABLE "TEST_AP"."ECM4" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(8) NOT NULL , "LineNum" INTEGER CS_INT, "ObjType" NVARCHAR(20) DEFAULT '-1' NOT NULL , "ObjXPath" NVARCHAR(254), "FieldType" NVARCHAR(1) DEFAULT 'T', "FieldXPath" NVARCHAR(254), "ImportFmt" INTEGER CS_INT, "UserSign" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "LogInstanc" SMALLINT CS_INT, "DflDSerie" INTEGER CS_INT DEFAULT -1, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ECM4_DOC_IMPORT" ON "TEST_AP"."ECM4" ( "Code" ASC, "ObjType" ASC, "AbsEntry" ASC )